  void _insertEmojiToChat(String emoji) {
    final value = _chatController.value;
    final start = value.selection.start >= 0
        ? value.selection.start
        : value.text.length;
    final end = value.selection.end >= 0 ? value.selection.end : start;
    final newText = value.text.replaceRange(start, end, emoji);
    _chatController.value = TextEditingValue(
      text: newText,
      selection: TextSelection.collapsed(offset: start + emoji.length),
    );
  }

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _viewData = GameViewDataSource.supabase(_supabase, widget.tableId);
    _game = OkeyGame(
      tableId: widget.tableId,
      isCreator: widget.isCreator,
      onTileSfx: _playTileSfx,
      onStartDealSfx: _playStartGameSfx,
    );
    _tileSfxPlayer.setReleaseMode(jo.ReleaseMode.stop);
    _startGameSfxPlayer.setReleaseMode(jo.ReleaseMode.stop);
    _turnTickSfxPlayer.setReleaseMode(jo.ReleaseMode.stop);

    _game.onHudChanged = () {
      if (mounted) setState(() {});
    };
    _game.onIndicatorBonusAwarded = _showIndicatorRewardFxBanner;
    _game.onFinishVisibilityChanged = (visible) {
      if (!mounted) return;
      setState(() {
        _setFinishPresentation(visible);
      });
    };

    _game.onFinish = () async {
      if (_showFinish) return; // ğŸ”¥ double trigger engelle

      setState(() {
        _showFinish = true;
      });

      _autoCloseFinish();
    };

    _myUserId = _supabase.auth.currentUser?.id;
    _prepareVoiceCoachmark();
    _bootstrap();
    _loadChatMessages();
    _subscribeRealtime();
    _refreshSpectators();
    _startUiLoops();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _prepareVisuals();
    });
    _hourglassCtrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 900),
    )..repeat(reverse: true);
    _voiceCommands.addListener(_onVoiceCommandsChanged);
    _voiceCommands.initialize();
    _spectatorVoiceStateSubscription = _audioPlayer.playerStateStream.listen((
      state,
    ) {
      if (state.processingState != ja.ProcessingState.completed || !mounted)
        return;
      final finishedId = _playingMessageId;
      setState(() => _playingMessageId = null);
      if (finishedId == null) return;
      for (final entry in _spectatorVoiceBubbles.entries.toList()) {
        if (entry.value['id'] == finishedId) {
          final spectatorId = entry.key;
          _spectatorBubbleTimers.remove(spectatorId)?.cancel();
          _spectatorBubbleTimers[spectatorId] = Timer(
            const Duration(seconds: 1),
            () {
              if (!mounted ||
                  _spectatorVoiceBubbles[spectatorId]?['id'] != finishedId)
                return;
              setState(() {
                _spectatorVoiceBubbles.remove(spectatorId);
                _spectatorBubbles.remove(spectatorId);
              });
            },
          );
        }
      }
    });
  }

  void _onVoiceCommandsChanged() {
    if (!mounted) return;
    final hasFeedback = _voiceCommands.feedback != null;
    if (hasFeedback) {
      _voiceFeedbackTimer?.cancel();
      _voiceFeedbackTimer = Timer(const Duration(seconds: 3), () {
        if (!mounted) return;
        _voiceCommands.clearFeedback();
      });
    }
    setState(() {});
  }

  void _setFinishPresentation(bool visible) {
    _hideTopHudForFinish = visible;
    if (visible) {
      if (_game.overlays.isActive('Avatars')) {
        _game.overlays.remove('Avatars');
      }
    } else {
      if (!_game.overlays.isActive('Avatars')) {
        _game.overlays.add('Avatars');
      }
    }
  }

  Future<void> _prepareVoiceCoachmark() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final key = '$_voiceCoachmarkKey:${_myUserId ?? 'guest'}';
      final seen = prefs.getBool(key) ?? false;
      if (!seen && mounted) {
        setState(() => _showVoiceCoachmark = true);
      }
    } catch (_) {
      // Best-effort only.
    }
  }

  Future<void> _dismissVoiceCoachmark() async {
    if (!_showVoiceCoachmark) return;
    if (mounted) {
      setState(() => _showVoiceCoachmark = false);
    }
    try {
      final prefs = await SharedPreferences.getInstance();
      final key = '$_voiceCoachmarkKey:${_myUserId ?? 'guest'}';
      await prefs.setBool(key, true);
    } catch (_) {}
  }

  Future<void> _prepareVisuals() async {
    try {
      await precacheImage(
        const AssetImage('assets/images/lobby/lobby.png'),
        context,
      );
      await precacheImage(const AssetImage('assets/images/table.png'), context);
    } catch (_) {
      // best effort
    }
    if (!mounted) return;
    setState(() => _visualReady = true);
  }

  Widget _buildTableBackdrop() =>
      Image.asset('assets/images/table.png', fit: BoxFit.fill);

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _syncDecorations();
  }

  void _syncDecorations() {
    final visible = _decorationsForeground && TickerMode.of(context);
    if (visible && !_hourglassCtrl.isAnimating) {
      _hourglassCtrl.repeat(reverse: true);
    } else if (!visible) {
      _hourglassCtrl.stop();
    }
  }

  @override
  void dispose() {
    _stopUiLoops();
    _tableViewRefresh.dispose();
    _playersViewRefresh.dispose();
    _viewData.dispose();
    _hudRevision.dispose();
    if (_tableChannel != null) {
      unawaited(_supabase.removeChannel(_tableChannel!));
    }
    if (_playersChannel != null) {
      unawaited(_supabase.removeChannel(_playersChannel!));
    }
    if (_chatChannel != null) {
      unawaited(_supabase.removeChannel(_chatChannel!));
    }
    if (_discardChannel != null) {
      unawaited(_supabase.removeChannel(_discardChannel!));
    }
    if (_spectatorsChannel != null) {
      unawaited(_supabase.removeChannel(_spectatorsChannel!));
    }
    _spectatorVoiceStateSubscription?.cancel();
    _spectatorBannerTimer?.cancel();
    for (final timer in _spectatorBubbleTimers.values) {
      timer.cancel();
    }
    _tablePoll?.cancel();
    _playersPoll?.cancel();
    for (final t in _avatarChatTimers.values) {
      t.cancel();
    }
    _avatarChatTimers.clear();
    _chatController.dispose();
    _player.dispose();
    _tileSfxPlayer.dispose();
    _startGameSfxPlayer.dispose();
    _turnTickSfxPlayer.dispose();
    _turnNoticeTimer?.cancel();
    _turnNoticeVisible.dispose();
    _turnNoticePlayer.dispose();
    _audioPlayer.dispose();
    _hourglassCtrl.dispose();
    _voiceFeedbackTimer?.cancel();
    _voiceCommands.removeListener(_onVoiceCommandsChanged);
    _voiceCommands.dispose();
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    _decorationsForeground = state == AppLifecycleState.resumed;
    if (!_decorationsForeground) {
      _turnNoticeTimer?.cancel();
      _turnNoticeVisible.value = false;
      unawaited(_turnNoticePlayer.stop());
    }
    _syncDecorations();
    if (state == AppLifecycleState.resumed) {
      _viewData.invalidateAll();
      _startUiLoops();
      unawaited(_loadTable());
      unawaited(_loadPlayers());
      return;
    }

    if (state == AppLifecycleState.detached) {
      // App kapatılırken, özellikle bekleme masasındaki yalnız creator için
      // masayı sunucu tarafında temizlemeyi best-effort olarak deneriz.
      unawaited(_leaveTableOnAppTerminate());
    }

    if (state == AppLifecycleState.inactive ||
        state == AppLifecycleState.paused ||
        state == AppLifecycleState.detached) {
      _stopUiLoops();
      if (_hourglassCtrl.isAnimating) {
        _hourglassCtrl.stop();
      }
    }
  }

  Future<void> _leaveTableOnAppTerminate() async {
    if (_isLeavingTable) return;
    final userId = _myUserId;
    if (userId == null) return;

    // Oyun başladıktan sonra masanın yaşam döngüsünü sunucu akışına bırakıyoruz.
    if (_tableStatus != 'waiting' && _tableStatus != 'start') return;

    _isLeavingTable = true;
    try {
      await _supabase.rpc(
        'leave_table',
        params: {'p_table_id': widget.tableId, 'p_user_id': userId},
      );
      await _waitUntilPlayerRemoved();
      await _cleanupTableIfInactive();
    } catch (_) {
      // App kapanışında best-effort çalışır; hata yutulur.
    }
  }

  void _startUiLoops() {
    if (_loopsRunning) return;
    _loopsRunning = true;
    _ticker = Timer.periodic(const Duration(milliseconds: 300), (_) {
      if (!mounted) return;
      _syncTurnTickSfx();
      // Keep sound cadence and game-owned clocks; notify only affected HUDs.
      final snapshot = (
        _game.gameStarted,
        _game.isHandReadyForPlay,
        _game.getCountdown(),
        _joinCountdown,
        _game.getRound(),
        _game.getPot(),
        _game.getLeague()?['name'],
        _game.getTableEntry(),
        _game.getTurnSeconds(),
      );
      if (snapshot != _lastHudSnapshot) {
        _lastHudSnapshot = snapshot;
        _hudRevision.value++;
      }
    });
    _tablePoll = Timer.periodic(const Duration(seconds: 2), (_) {
      _loadTable();
    });
    _playersPoll = Timer.periodic(const Duration(seconds: 2), (_) {
      _loadPlayers();
    });
  }

  void _stopUiLoops() {
    _loopsRunning = false;
    _ticker?.cancel();
    _ticker = null;
    _tablePoll?.cancel();
    _tablePoll = null;
    _playersPoll?.cancel();
    _playersPoll = null;
  }

  Future<void> _bootstrap() async {
    await FeedbackSettingsService.load();
    await _loadTable();
    await _loadPlayers();
    await _loadDiscardHistory();
  }

  void _subscribeRealtime() {
    _tableChannel?.unsubscribe();
    _tableChannel = _supabase
        .channel('okey_screen_table_${widget.tableId}')
        .onPostgresChanges(
          event: PostgresChangeEvent.update,
          schema: 'public',
          table: 'tables',
          filter: PostgresChangeFilter(
            type: PostgresChangeFilterType.eq,
            column: 'id',
            value: widget.tableId,
          ),
          callback: (payload) {
            _viewData.tableChanged(payload.commitTimestamp.toString());
            _loadTable();
          },
        )
        .subscribe((status, error) {
          if (status == RealtimeSubscribeStatus.subscribed) {
            _viewData.invalidateAll();
            unawaited(_loadTable());
            unawaited(_loadPlayers());
          }
        });

    _playersChannel?.unsubscribe();
    _playersChannel = _supabase
        .channel('okey_screen_players_${widget.tableId}')
        .onPostgresChanges(
          event: PostgresChangeEvent.all,
          schema: 'public',
          table: 'table_players',
          filter: PostgresChangeFilter(
            type: PostgresChangeFilterType.eq,
            column: 'table_id',
            value: widget.tableId,
          ),
          callback: (payload) {
            _viewData.playersChanged(payload.commitTimestamp.toString());
            _loadPlayers();
          },
        )
        .subscribe((status, error) {
          if (status == RealtimeSubscribeStatus.subscribed) {
            _viewData.invalidateAll();
            unawaited(_loadTable());
            unawaited(_loadPlayers());
          }
        });

    _discardChannel?.unsubscribe();
    _spectatorsChannel = _supabase
        .channel('okey_screen_spectators_${widget.tableId}')
        .onPostgresChanges(
          event: PostgresChangeEvent.all,
          schema: 'public',
          table: 'table_spectators',
          callback: (_) => _refreshSpectators(),
        )
        .subscribe((status, error) {
          if (status == RealtimeSubscribeStatus.subscribed) {
            unawaited(_refreshSpectators());
          }
        });

    _discardChannel = _supabase
        .channel('okey_screen_discards_${widget.tableId}')
        .onPostgresChanges(
          event: PostgresChangeEvent.all,
          schema: 'public',
          table: 'table_discards',
          filter: PostgresChangeFilter(
            type: PostgresChangeFilterType.eq,
            column: 'table_id',
            value: widget.tableId,
          ),
          callback: (_) => _loadDiscardHistory(),
        )
        .subscribe();

    _chatChannel = _supabase
        .channel('okey_screen_chat_${widget.tableId}')
