          schema: 'public',
          table: 'table_messages',
          filter: PostgresChangeFilter(
            type: PostgresChangeFilterType.eq,
            column: 'table_id',
            value: widget.tableId,
          ),
          callback: (payload) async {
            final raw = payload.newRecord;

            final msg = Map<String, dynamic>.from(raw);

            final senderId = msg['sender_id']?.toString();
            unawaited(_handleIncomingRealtimeMessage(msg));
            await _ensureUserLoaded(senderId);
            if (!mounted) return;
            final username = _userNames[senderId];
            if (username != null) {
              setState(() {
                for (final existing in _chatMessages) {
                  if (existing['id'] == msg['id']) {
                    existing['users'] = {'username': username};
                  }
                }
              });
            }
          },
        )
        .subscribe((status, err) {
          if (err != null) {
            print("CHAT ERROR: $err");
          }
        });
  }

  Future<void> _refreshSpectators() async {
    try {
      final rows = await _supabase
          .from('table_spectators')
          .select()
          .eq('table_id', widget.tableId);
      final list = (rows as List)
          .map((e) => Map<String, dynamic>.from(e as Map))
          .toList();
      list.sort((a, b) => (a['created_at'] ?? a['joined_at'] ?? '')
          .toString().compareTo((b['created_at'] ?? b['joined_at'] ?? '').toString()));
      final visible = list.take(3).toList();
      // Avatar metadata must never prevent an occupied spectator slot appearing.
      for (final item in visible) {
        final id = item['user_id']?.toString();
        if (id == null || id.isEmpty) continue;
        final previous = _visibleSpectators.where((p) => p['user_id']?.toString() == id);
        if (previous.isNotEmpty) item['users'] = previous.first['users'];
      }
      if (!mounted) return;
      setState(() => _visibleSpectators = visible);
      final ids = visible.map((p) => p['user_id']?.toString())
          .whereType<String>().where((id) => id.isNotEmpty).toList();
      if (ids.isEmpty) return;
      try {
        final users = await _supabase.from('users')
            .select('id,username,avatar_url').inFilter('id', ids);
        final byId = {for (final user in users) user['id'].toString(): user};
        if (!mounted) return;
        setState(() {
          for (final item in _visibleSpectators) {
            final user = byId[item['user_id']?.toString()];
            if (user != null) item['users'] = user;
          }
        });
      } catch (e) {
        debugPrint('SPECTATOR AVATAR METADATA ERROR: $e');
      }
    } catch (e) {
      debugPrint('SPECTATOR PRESENCE ERROR: $e');
    }
  }
  String _spectatorName(String name) {
    final chars = name.trim().runes.toList();
    if (chars.length <= 10) return name.trim();
    return '${String.fromCharCodes(chars.take(10))}…';
  }

  Widget _spectatorStrip() {
    if (_visibleSpectators.isEmpty) return const SizedBox.shrink();
    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.end,
      children: _visibleSpectators.map((entry) {
        final id = entry['user_id']?.toString() ?? '';
        final user = entry['users'] is Map ? entry['users'] as Map : const {};
        final name = (user['username'] ?? 'İzleyici').toString();
        final path = (user['avatar_url'] ?? '').toString();
        final message = _spectatorBubbles[id];
        final voiceMessage = _spectatorVoiceBubbles[id];
        return TweenAnimationBuilder<double>(
          key: ValueKey('spectator-entry-$id'),
          tween: Tween(begin: 0, end: 1),
          duration: const Duration(milliseconds: 480),
          curve: Curves.easeOutBack,
          builder: (context, progress, child) => Opacity(
            opacity: progress.clamp(0.0, 1.0),
            child: Transform.translate(
              offset: Offset(45 * (1 - progress), 0),
              child: Transform.scale(
                scale: 0.88 + 0.12 * progress,
                alignment: Alignment.centerRight,
                child: child,
              ),
            ),
          ),
          child: Padding(
            padding: const EdgeInsets.only(bottom: 6),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                if (message != null || voiceMessage != null) ...[
                  Container(
                    constraints: BoxConstraints(
                      maxWidth: voiceMessage != null ? 140 : 118,
                    ),
                    padding: const EdgeInsets.symmetric(
                      horizontal: 8,
                      vertical: 6,
                    ),
                    decoration: BoxDecoration(
                      color: const Color(0xED172129),
                      borderRadius: const BorderRadius.only(
                        topLeft: Radius.circular(12),
