  bool _openFinishFromTableRow(
    Map<String, dynamic> row,
    String winnerName,
    bool isWinner,
  ) {
    final rawSlots = row['last_final_slots'];
    final rawFinishTile = row['last_finish_tile'];
    if (rawSlots == null || rawSlots is! List || rawFinishTile == null) {
      return false;
    }

    final slots = List<Map<String, dynamic>>.from(rawSlots);
    final finishTile = Map<String, dynamic>.from(
      rawFinishTile as Map<dynamic, dynamic>,
    );
    final winAmount = (row['last_win_amount'] as num?)?.toInt() ?? 0;
    final isDraw = ((row['pot_amount'] as num?)?.toInt() ?? 1) == 0;

    _game.showFinishFromGame(
      slots,
      finishTile,
      winnerName,
      isWinner,
      false,
      winAmount,
      isDraw,
      false,
    );

    setState(() {
      _finishSlots = slots;
      _showFinish = true;
    });
    _autoCloseFinish();
    return true;
  }

  Future<void> _autoCloseFinish() async {
    await Future.delayed(const Duration(milliseconds: 4000));

    if (!mounted) return;
    _game.hideFinish();
    setState(() {
      _showFinish = false;
    });
  }

  void _syncTurnTickSfx() {
    final turnActive =
        _tableStatus == 'playing' &&
        !_hideTopHudForFinish &&
        _game.isMyTurnForLocalUser;

    if (turnActive != _localTurnWasActive) {
      _localTurnWasActive = turnActive;
      _turnNoticeTimer?.cancel();
      _turnNoticeVisible.value = turnActive;
      if (turnActive && _decorationsForeground) {
        unawaited(FeedbackSettingsService.triggerHaptic());
        if (FeedbackSettingsService.soundEnabled) {
          unawaited(_playTurnNotice());
        }
        _turnNoticeTimer = Timer(const Duration(milliseconds: 1800), () {
          if (mounted) _turnNoticeVisible.value = false;
        });
      }
    }

    if (!turnActive || !FeedbackSettingsService.soundEnabled) {
      _lastTurnTickSecond = null;
      _turnTickSfxPlayer.stop();
      return;
    }

    final turnSeconds = _game.getTurnSeconds();
    if (turnSeconds <= 0) {
      _lastTurnTickSecond = null;
      _turnTickSfxPlayer.stop();
      return;
    }

    final remaining = (_game.getTurnProgress() * turnSeconds).ceil().clamp(
      0,
      turnSeconds,
    );

    if (remaining <= 0) {
      _lastTurnTickSecond = null;
      _turnTickSfxPlayer.stop();
      return;
    }

    if (_lastTurnTickSecond == remaining) return;
    _lastTurnTickSecond = remaining;

    _turnTickSfxPlayer.stop();
    if (remaining <= 5) {
      _turnTickSfxPlayer.play(
        jo.AssetSource('sounds/turn_soft_tick.wav'),
        volume: 0.16,
      );
    }
  }

  Future<void> _loadTable() => _tableViewRefresh.run(_loadTableOnce);

  Future<void> _playTurnNotice() async {
    try {
      await _turnNoticePlayer.play(
        jo.AssetSource('sounds/turn_notice.wav'),
        volume: 0.30,
      );
    } catch (error) {
      debugPrint('Turn notice audio: $error');
    }
  }

  Future<void> _loadTableOnce() async {
    unawaited(_loadSessionScore());
    try {
      final row = await _viewData.table();
      if (!mounted) return;

      if (row == null) return;

      final status = row['status']?.toString() ?? 'waiting';
      final maxPlayers = (row['max_players'] as int?) ?? 2;
      final readySince = _parseServerTime(row['ready_since']);
      final finishAt = _parseServerTime(row['last_finish_at']);
      final chatEnabled = (row['chat_enabled'] as bool?) ?? true;
      final spectatorsEnabled = (row['spectators_enabled'] as bool?) ?? true;

      _tableStatus = status;
      _maxPlayers = maxPlayers;
      _lastFinishAt = finishAt;
      _tableChatEnabled = chatEnabled;
      _tableSpectatorsEnabled = spectatorsEnabled;

      // If a fresh game has started, clear any stale finish overlay state.
      if (_tableStatus == 'playing' && _game.isFinishOpen) {
        _game.hideFinish();
        _showFinish = false;
      }

      _readySince = (_tableStatus == 'waiting' || _tableStatus == 'start')
          ? readySince
          : null;

      if (!_tableChatEnabled && _chatOpen) {
        _chatOpen = false;
        _showEmojiPicker = false;
      }


      if (mounted) setState(() {});
    } catch (e) {
      debugPrint('TABLE LOAD ERROR: $e');
    }
  }

  Future<void> _loadPlayers() => _playersViewRefresh.run(_loadPlayersOnce);

  Future<void> _loadSessionScore() async {
    final user = _supabase.auth.currentUser?.id;
    final table = widget.tableId;
    if (user == null || _viewData.tableId != table) return;
    try {
      final score = await _viewData.sessionScore();
      if (!mounted || widget.tableId != table || _viewData.tableId != table ||
          _supabase.auth.currentUser?.id != user || score['table_id'] != table) {
        return;
      }
      final wins = (score['wins'] as num?)?.toInt() ?? 0;
      final losses = (score['losses'] as num?)?.toInt() ?? 0;
      if (_scoreUserId == user && _sessionWins == wins && _sessionLosses == losses) return;
      setState(() {
        _scoreUserId = user;
        _sessionWins = wins;
        _sessionLosses = losses;
      });
    } catch (_) {
      // Keep the last confirmed result on transient read failures; the existing
      // table refresh retries. No extra timer, writer call or client-side win count.
    }
  }

  Future<void> _loadPlayersOnce() async {
    try {
      final rows = await _viewData.players();
      if (!mounted) return;

      final players = (rows as List)
          .map((e) => Map<String, dynamic>.from(e as Map))
          .toList();

      final currentUserId = _myUserId;
      if (currentUserId != null &&
          !players.any((p) => p['user_id']?.toString() == currentUserId)) {
        _selfMissingStreak++;
        final stillInTable = await _confirmSelfStillInTable(currentUserId);
        if (stillInTable) {
          _selfMissingStreak = 0;
          return;
        }
        if (_selfMissingStreak < 4) {
          return;
        }
        _selfMissingStreak = 0;
        if (mounted && !_isLeavingTable) {
          _showSnack('Süre aşımı nedeniyle masadan çıkarıldınız.');
          _leaveTable();
        }
        return;
      }
      _selfMissingStreak = 0;

      _playerCount = players.length;
      final mySeat = players
          .where((p) => p['user_id']?.toString() == _myUserId)
          .map((p) => p['seat_index'] as int?)
          .cast<int?>()
          .firstWhere((v) => v != null, orElse: () => null);
      _mySeatIndex = mySeat;
      final myRow = players.cast<Map<String, dynamic>?>().firstWhere(
        (p) => p != null && p['user_id']?.toString() == _myUserId,
        orElse: () => null,
      );
      _doubleMode = myRow?['is_double_mode'] == true;

      if (_tableStatus == 'waiting' && _playerCount >= _maxPlayers) {
        _readySince ??= DateTime.now();
      } else {
        _readySince = null;
      }

      final ids = players
          .map((e) => e['user_id']?.toString())
          .whereType<String>()
          .where((e) => e.isNotEmpty)
          .toSet()
          .toList();

      if (ids.isNotEmpty) {
        final rows = await _viewData.users(ids);
        if (!mounted || !_viewData.matchesMembers(ids)) return;
        _userNames.removeWhere((id, _) => !ids.contains(id));
        for (final raw in (rows as List)) {
          final row = Map<String, dynamic>.from(raw as Map);
          final id = row['id']?.toString();
          if (id == null || id.isEmpty) continue;
          final username = row['username']?.toString().trim();
          final email = row['email']?.toString().trim();
          _userNames[id] = (username != null && username.isNotEmpty)
              ? username
              : (email ?? 'Oyuncu');
        }
      }

      if (mounted) setState(() {});
    } catch (e) {
      debugPrint('PLAYER LOAD ERROR: $e');
    }
  }

  Future<void> _loadDiscardHistory() async {
    try {
      final rows = await _supabase
          .from('table_discards')
          .select('seat_index,tile,created_at')
          .eq('table_id', widget.tableId)
          .order('created_at', ascending: true);

      _discardRows = (rows as List)
          .map((e) => Map<String, dynamic>.from(e as Map))
          .toList();
      if (mounted) setState(() {});
    } catch (e) {
      debugPrint('DISCARD HISTORY ERROR: $e');
    }
  }

  Future<void> _loadChatMessages() async {
    if (_chatLoading) return;

    _chatLoading = true;

    try {
      final rows = await _supabase
          .from('table_messages')
          .select('*,users(username)')
          .eq('table_id', widget.tableId)
          .order('created_at', ascending: false)
          .limit(200);

      _chatMessages = (rows as List)
          .reversed
          .map((e) => Map<String, dynamic>.from(e as Map))
          .toList();

      if (mounted) setState(() {});

