    final username = _userNames[senderId] ?? 'Oyuncu';

    final enriched = {
      ...msg,
      'users': {'username': username},
    };

    _chatMessages.add(enriched);

    if (mounted) setState(() {});

    _scrollToBottom();

    if (TableChatMembershipEvent.matches(enriched)) return;
    final role = (enriched['role'] ?? 'player').toString();
    if (role == 'player') {
      _showAvatarChatBubble(enriched);
    } else if (role == 'spectator' && senderId != _myUserId) {
      await _refreshSpectators();
      if (!mounted) return;
      _showSpectatorBubble(enriched);
      if (!_visibleSpectators.any(
        (e) => e['user_id']?.toString() == senderId.toString(),
      ))
        _showIncomingMessage(enriched);
    }
  }

  void _showAvatarChatBubble(Map<String, dynamic> msg) {
    final senderId = msg['sender_id']?.toString();
    if (senderId == null || senderId.isEmpty) return;
    final type = (msg['type'] ?? 'text').toString();
    final rawText = type == 'voice'
        ? 'Sesli mesaj'
        : (msg['content']?.toString() ?? '');
    final text = _shortText(rawText.trim(), max: 34);
    if (text.isEmpty) return;

    _avatarChatTimers[senderId]?.cancel();
    if (mounted) {
      setState(() {
        _avatarChatByUserId[senderId] = text;
      });
    }
    _avatarChatTimers[senderId] = Timer(const Duration(seconds: 3), () {
      if (!mounted) return;
      setState(() {
        _avatarChatByUserId.remove(senderId);
      });
      _avatarChatTimers.remove(senderId);
    });
  }

  bool _sendingTextMessage = false;

  Future<void> _sendMessage() async {
    final message = _chatController.text.trim();
    final senderId = _myUserId;
    if (message.isEmpty || senderId == null || _sendingTextMessage) return;

    _sendingTextMessage = true;
    final row = <String, dynamic>{
      'id': const Uuid().v4(),
      'table_id': widget.tableId,
      'sender_id': senderId,
      'content': message,
      'role': 'player',
      'type': 'text',
    };
    try {
      await _supabase.from('table_messages').insert(row);
      if (!mounted) return;
      if (_chatController.text.trim() == message) _chatController.clear();
      FocusManager.instance.primaryFocus?.unfocus();
      await _handleIncomingRealtimeMessage({
        ...row,
        'created_at': DateTime.now().toUtc().toIso8601String(),
      });
    } catch (error) {
      debugPrint('PLAYER CHAT SEND ERROR: $error');
      if (mounted) _showSnack('Mesaj gönderilemedi. Tekrar deneyin.');
    } finally {
      _sendingTextMessage = false;
    }
  }
  void _showSnack(String text) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(text)));
  }

