              SafeArea(
                child: Stack(
                  // During play the waiting layer becomes SizedBox.shrink().
                  // Keep this HUD full-size so right-aligned spectators and
                  // message banners are not positioned outside a zero-size stack.
                  fit: StackFit.expand,
                  children: [
                    ValueListenableBuilder<int>(
                      valueListenable: _hudRevision,
                      builder: (_, _, _) =>
                          !finishOverlayOpen &&
                               (_tableStatus == 'waiting' ||
                                    _tableStatus == 'start' ||
                                    _tableStatus == 'playing') &&
                                !_game.isHandReadyForPlay
                          ? _buildWaitingOverlay()
                          : const SizedBox.shrink(),
                    ),
                    if (!finishOverlayOpen && _menuOpen) _buildMenuPanel(),
                    if (_showIndicatorRewardFx) _buildIndicatorRewardFx(),
                    if (!finishOverlayOpen && _visibleSpectators.isNotEmpty)
                      Positioned(top: 89, right: 8, child: _spectatorStrip()),
                    if (!finishOverlayOpen &&
                        _showMessageBanner &&
                        _lastIncomingMessage != null)
                      Positioned(
                        top: 60,
                        right: 12,
                        width: MediaQuery.of(context).size.width * 0.28,
                        child: AnimatedSlide(
                          duration: const Duration(milliseconds: 300),
                          offset: _showMessageBanner
                              ? Offset.zero
                              : const Offset(1, 0),
                          child: AnimatedOpacity(
                            duration: const Duration(milliseconds: 300),
                            opacity: _showMessageBanner ? 1 : 0,
                            child: IgnorePointer(child: _buildMessageBanner()),
                          ),
                        ),
                      ),
                  ],
                ),
              ),
              if (!finishOverlayOpen)
                SafeArea(
                  child: Stack(
                    fit: StackFit.expand,
                    children: [
                      ValueListenableBuilder<int>(
                        valueListenable: _hudRevision,
                        builder: (_, _, _) => _buildTopLeftPanel(),
                      ),
                      ValueListenableBuilder<int>(
                        valueListenable: _hudRevision,
                        builder: (_, _, _) => _buildTopRightLeague(),
                      ),
                      _buildVoiceCommandHud(),
                      if (_showVoiceCoachmark) _buildVoiceCoachmark(),
                      if (_chatOpen) _buildChatPanel(),
                    ],
                  ),
                ),
              if (finishOverlayOpen) _buildFinishLeaveButton(),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildFinishLeaveButton() {
    final result = _game.finishView;
    if (result == null) return const SizedBox.shrink();
    return GameFinishPresentation(
      key: ObjectKey(result),
      winner: result.isWinner,
      spectator: result.isSpectator,
      amount: result.winAmount,
      winnerName: result.winnerName,
      okeyFinish: result.isOkeyFinish,
      doubleFinish: result.isDoubleFinish,
      leaving: _isLeavingTable,
      onLeave: _leaveTable,
    );
  }

  double get _topBarWidth {
    final media = MediaQuery.of(context);
    final avatarWidth = (media.size.width * .30).clamp(196.0, 224.0);
    final usableWidth = media.size.width - media.padding.horizontal;
    return ((usableWidth - avatarWidth - 32) / 2).clamp(100.0, 210.0);
  }

  Widget _buildTopLeftPanel() {
    final pot = _game.getPot();

    return Positioned(
      top: 10,
      left: 6,
      width: _topBarWidth,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Container(
            width: double.infinity,
            height: 48,
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 7),
            decoration: BoxDecoration(
              gradient: const LinearGradient(
                begin: Alignment.topLeft,
                end: Alignment.bottomRight,
                colors: [Color(0x661A2622), Color(0x66101714)],
              ),
              borderRadius: BorderRadius.circular(18),
              border: Border.all(color: const Color(0x66DAB971), width: 1.0),
              boxShadow: const [
                BoxShadow(
                  color: Color(0x29000000),
                  blurRadius: 8,
                  offset: Offset(0, 4),
                ),
              ],
            ),
            child: FittedBox(
              fit: BoxFit.scaleDown,
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  /// ğŸ”¥ EXIT (gold minimal)
                  _exitButton(),
                  const SizedBox(width: 8),

                  _settingsButton(),
                  _divider(),

                  /// ğŸ”¥ ROUND
                  Row(
                    children: [
                      _infoPill(
                        icon: Icons.monetization_on_rounded,
                        text: Format.coin(_game.getTableEntry()),
                        textColor: const Color(0xFFE7C77B),
                        colors: const [Color(0xFF253129), Color(0xFF141B17)],
                        fontFamily: 'Orbitron',
                      ),
                    ],
                  ),

                  _divider(),

                  /// ğŸ”¥ POT (Ã‡ANAK - PREMIUM)
                  Row(
                    children: [
                      /// ğŸ”¥ COIN ICON (bÃ¼yÃ¼k, sade)
                      const Icon(
                        Icons.monetization_on,
                        size: 20,
                        color: Color(0xFFFFC107), // hafif gold ama glow yok
                      ),

                      const SizedBox(width: 6),

                      /// ğŸ”¥ VALUE
                      TweenAnimationBuilder<double>(
                        tween: Tween<double>(end: pot.toDouble()),
                        duration: const Duration(milliseconds: 500),
                        curve: Curves.easeOutCubic,
                        builder: (context, value, child) {
                          return Text(
                            Format.balance(value.round()),
                            style: const TextStyle(
                              fontFamily: "Orbitron",
                              fontWeight: FontWeight.w900,
                              color: Color(0xFFFFD56A),
                              fontSize: 15,
                              letterSpacing: 0.6,
                            ),
                          );
                        },
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(height: 4),
          Padding(
            padding: const EdgeInsets.only(left: 18),
            child: TableSessionScore(
            wins:
                _scoreUserId == _supabase.auth.currentUser?.id &&
                    _viewData.tableId == widget.tableId
                ? _sessionWins
                : 0,
            losses:
                _scoreUserId == _supabase.auth.currentUser?.id &&
                    _viewData.tableId == widget.tableId
                ? _sessionLosses
                : 0,
          )),
        ],
      ),
    );
  }

  Widget _buildVoiceCoachmark() {
    return Positioned(
      top: 90,
      left: 8,
      child: Container(
        width: 340,
        padding: const EdgeInsets.fromLTRB(12, 10, 10, 10),
        decoration: BoxDecoration(
          color: const Color(0x66101814),
          borderRadius: BorderRadius.circular(14),
          border: Border.all(color: const Color(0x66DAB971)),
          boxShadow: const [
            BoxShadow(
              color: Color(0x33000000),
              blurRadius: 8,
              offset: Offset(0, 4),
            ),
          ],
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
