  void _closeTableChat() {
    FocusManager.instance.primaryFocus?.unfocus();
    _isPressing = false;
    if (_isRecording) {
      unawaited(Future<void>.delayed(const Duration(milliseconds: 300), () async {
        if (mounted && !_chatOpen) await _stopRecording(send: false);
      }));
    }
    setState(() {
      _chatOpen = false;
      _showEmojiPicker = false;
    });
  }

  Widget _buildChatPanel() {
    return TableChatPanel(
      controller: _chatController,
      scrollController: _chatScroll,
      messageCount: _chatMessages.length,
      onClose: _closeTableChat,
      onSend: _sendMessage,
      onQuickMessage: (message) {
        _chatController.text = message;
        unawaited(_sendMessage());
      },
      onEmoji: () {
        setState(() => _showEmojiPicker = !_showEmojiPicker);
        _scrollToBottom();
      },
      microphone: Listener(
        onPointerDown: (_) async {
          _isPressing = true;
          await Future<void>.delayed(const Duration(milliseconds: 250));
          if (_isPressing && mounted && _chatOpen) await _startRecording();
        },
        onPointerUp: (_) async {
          _isPressing = false;
          await _stopRecording(send: false);
        },
        onPointerCancel: (_) async {
          _isPressing = false;
          await _stopRecording(send: false);
        },
        child: _recordButton(),
      ),
      accessory: Column(mainAxisSize: MainAxisSize.min, children: [
        if (_showPreview && _previewPath != null) Row(children: [
          IconButton(
            tooltip: 'Kaydı dinle',
            icon: const Icon(Icons.play_arrow_rounded, color: TableChatPanel.gold),
            onPressed: () async {
              if (!FeedbackSettingsService.soundEnabled) {
                await FeedbackSettingsService.triggerHaptic();
                return;
              }
              await _audioPlayer.setFilePath(_previewPath!);
              await _audioPlayer.play();
              await FeedbackSettingsService.triggerHaptic();
            },
          ),
          Expanded(child: ClipRect(child: _waveform(false))),
          IconButton(
            tooltip: 'Kaydı sil',
            icon: const Icon(Icons.close_rounded, color: Colors.white60),
            onPressed: () async {
              final path = _previewPath;
              if (path == null) return;
              await File(path).delete();
              if (!mounted) return;
              setState(() { _previewPath = null; _showPreview = false; });
            },
          ),
          IconButton(
            tooltip: 'Sesli mesaj gönder',
            icon: const Icon(Icons.send_rounded, color: TableChatPanel.gold),
            onPressed: () async {
              final path = _previewPath;
              if (path == null) return;
              await sendVoiceMessage(path);
              if (!mounted) return;
              setState(() { _previewPath = null; _showPreview = false; });
            },
          ),
        ]),
        if (_showEmojiPicker) SizedBox(height: 38, child: ListView(
          scrollDirection: Axis.horizontal,
          children: _chatEmojis.map((emoji) => InkWell(
            onTap: () => _insertEmojiToChat(emoji),
            child: Padding(padding: const EdgeInsets.all(5),
              child: Text(emoji, style: const TextStyle(fontSize: 22))),
          )).toList(),
        )),
      ]),
      messageBuilder: (context, index) {
        final msg = _chatMessages[index];
        if (TableChatMembershipEvent.matches(msg)) {
          return TableChatMembershipEvent(event: Map<String, dynamic>.from(msg['membership_event']));
        }
        final senderId = msg['sender_id']?.toString();
        final mine = senderId == _myUserId;
        final spectator = msg['role'] == 'spectator';
        final name = (msg['users']?['username'] ?? _userNames[senderId] ?? 'Oyuncu').toString();
        return Align(
          alignment: mine ? Alignment.centerRight : Alignment.centerLeft,
          child: Container(
            margin: const EdgeInsets.symmetric(vertical: 3),
            padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 6),
            decoration: BoxDecoration(
              color: mine ? const Color(0x22DABF82) : const Color(0x251E2A36),
              borderRadius: BorderRadius.circular(10),
            ),
            child: Column(mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(spectator ? '$name · İzleyici' : name,
                style: TextStyle(color: spectator ? const Color(0xFFA9BDC9) : TableChatPanel.gold,
                  fontSize: 10, fontWeight: FontWeight.w600)),
              const SizedBox(height: 3),
              if (msg['type'] == 'voice') _voiceBubble(msg, mine)
              else Text(msg['content']?.toString() ?? '',
                style: const TextStyle(color: Color(0xFFE7EBE8), fontSize: 12, height: 1.3)),
            ]),
          ),
        );
      },
    );
  }
